const UpdaterUI=(()=>{
 const state={status:'idle',version:'',progress:0,message:'',notes:null,checking:false,checkedAt:0,autoPrompted:false};
 const bridge=()=>window.desktopUpdater;
 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const signedIn=()=>!!(window.cloudSession?.access_token&&window.cloudSession?.user);
 function settingsRow(){return `<div class="settings-row updater-settings-row"><div><strong>Software updates</strong><p id="updaterSettingsStatus">${esc(statusText())}</p></div><div class="updater-settings-actions"><button class="secondary-btn" id="updaterNotesSettings">${typeof icon==='function'?icon('external'):''}Release notes</button><button class="secondary-btn" id="updaterCheckSettings">Check for updates</button></div></div>`}
 function statusText(){if(!bridge())return 'Updates are available in the Windows desktop app.';if(!signedIn())return 'Sign in to check for updates.';if(state.status==='available')return `Version ${state.version} is ready to download.`;if(state.status==='downloaded')return `Version ${state.version} is ready to install.`;if(state.status==='current')return `You’re up to date${state.checkedAt?` · checked ${new Date(state.checkedAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`:''}.`;if(state.status==='error')return state.message||'Could not check for updates.';if(state.status==='checking')return 'Checking for the latest version…';return 'Checks for new features and security updates.'}
 function updateSettingsStatus(){const el=document.querySelector('#updaterSettingsStatus');if(el)el.textContent=statusText()}
 function notesMarkup(notes){const body=String(notes?.body||'').trim();const lines=body?body.split(/\r?\n/).map(line=>{const t=line.trim();if(!t)return '';if(/^#{1,3}\s/.test(t))return `<h3>${esc(t.replace(/^#{1,3}\s/,''))}</h3>`;if(/^[-*]\s/.test(t))return `<p class="updater-note-bullet">${esc(t.replace(/^[-*]\s/,''))}</p>`;return `<p>${esc(t)}</p>`}).join(''):'<p>Release notes are not available for this version yet.</p>';return `<div class="modal-header"><div><div class="eyebrow">WHAT’S NEW</div><h2 id="modalTitle">${esc(notes?.name||`Sam’s Canvas ${notes?.version||''}`)}</h2><p>${esc(notes?.published_at?new Date(notes.published_at).toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'}):'Release notes')}</p></div>${typeof closeButton==='function'?closeButton():''}</div><div class="updater-release-notes">${lines}</div><div class="modal-actions"><button class="primary-btn" data-close>Done</button></div>`}
 async function viewNotes(){if(!bridge())return typeof toast==='function'?toast('Release notes are available in the desktop app.'):null;if(!signedIn())return typeof toast==='function'?toast('Sign in to view private release notes.'):null;showModal(`<div class="modal-header"><div><div class="eyebrow">RELEASE NOTES</div><h2 id="modalTitle">A moment…</h2><p>Fetching the latest changes.</p></div>${typeof closeButton==='function'?closeButton():''}</div><div class="updater-release-notes"><p>Loading release notes…</p></div>`);try{const notes=await bridge().releaseNotes(window.cloudSession.access_token);if(!document.querySelector('#modalBackdrop')?.classList.contains('hidden'))showModal(notesMarkup(notes))}catch(error){if(typeof toast==='function')toast(error?.message||'Could not load release notes.');closeModal()}}
 function updateModal(mode){const map={available:{eyebrow:'A NEW VERSION IS READY',title:`Sam’s Canvas ${state.version}`,copy:'A fresh set of improvements is ready. Download it now and install when it’s ready.',action:'Download update'},progress:{eyebrow:'DOWNLOADING UPDATE',title:`Getting ${state.version} ready`,copy:`${Math.round(state.progress)}% · ${state.message||'Downloading securely from your private release.'}`,action:''},downloaded:{eyebrow:'READY WHEN YOU ARE',title:'Update downloaded',copy:`Sam’s Canvas ${state.version} is ready to install. The app will close briefly and reopen with the update.`,action:'Install update'},error:{eyebrow:'UPDATE CHECK',title:'Couldn’t check right now',copy:state.message||'The update service could not be reached. Check your connection and try again.',action:'Try again'}};const item=map[mode];if(!item)return;showModal(`<div class="update-dialog"><div class="update-orbit"><span>SC</span></div><div class="eyebrow">${item.eyebrow}</div><h2 id="modalTitle">${item.title}</h2><p>${esc(item.copy)}</p>${mode==='progress'?`<div class="update-progress"><span style="width:${Math.max(2,Math.min(100,state.progress))}%"></span></div>`:''}<div class="update-dialog-actions"><button type="button" class="secondary-btn" id="updaterViewChanges">View release notes</button>${item.action?`<button type="button" class="primary-btn" id="updaterMainAction">${item.action}</button>`:''}</div></div>`,false);document.querySelector('#updaterViewChanges')?.addEventListener('click',viewNotes);document.querySelector('#updaterMainAction')?.addEventListener('click',()=>{if(mode==='available')download();else if(mode==='downloaded')bridge()?.install();else if(mode==='error')check(false)})}
 async function download(){if(!bridge())return;state.status='progress';state.progress=0;updateModal('progress');try{await bridge().download()}catch(error){state.status='error';state.message=error?.message||'The update could not be downloaded.';updateModal('error');updateSettingsStatus()}}
 async function check(auto=false){if(!bridge()||!signedIn()||state.checking)return;if(!window.cloudSession?.access_token)return;state.checking=true;state.status='checking';state.message='';updateSettingsStatus();try{await bridge().check(window.cloudSession.access_token);state.checkedAt=Date.now()}catch(error){state.status='error';state.message=error?.message||'Update service is not available yet.'}finally{state.checking=false;updateSettingsStatus();if(state.status==='available'&&(!auto||!state.autoPrompted)){state.autoPrompted=true;setTimeout(()=>updateModal('available'),auto?900:100)}}}
 function onEvent(event){if(!event)return;switch(event.type){case'checking':state.status='checking';break;case'available':state.status='available';state.version=event.version||'';break;case'current':state.status='current';state.checkedAt=Date.now();break;case'progress':state.status='progress';state.progress=event.percent||0;state.message=event.bytesPerSecond?`${(event.bytesPerSecond/1024/1024).toFixed(1)} MB/s`:'';{const bar=document.querySelector('.update-progress span'),copy=document.querySelector('.update-dialog>p');if(bar&&copy){bar.style.width=`${Math.max(2,Math.min(100,state.progress))}%`;copy.textContent=`${Math.round(state.progress)}% · ${state.message||'Downloading securely from your private release.'}`}else updateModal('progress')}break;case'downloaded':state.status='downloaded';state.version=event.version||state.version;updateModal('downloaded');break;case'error':state.status='error';state.message=event.message||'Could not check for updates.';if(document.querySelector('#modalBackdrop')&&!document.querySelector('#modalBackdrop').classList.contains('hidden'))updateModal('error');break}updateSettingsStatus()}
 async function sessionChanged(){if(!bridge()||!signedIn())return;try{await bridge().setToken(window.cloudSession.access_token)}catch{}if(!state.checkedAt&&!state.checking)setTimeout(()=>check(true),1300)}
 function bindSettings(){document.querySelector('#updaterCheckSettings')?.addEventListener('click',()=>check(false));document.querySelector('#updaterNotesSettings')?.addEventListener('click',viewNotes);updateSettingsStatus()}
 if(bridge())bridge().onEvent(onEvent);
 window.addEventListener('online',()=>{if(signedIn()&&state.status==='error')check(true)});
 return{settingsRow,bindSettings,sessionChanged,check,viewNotes};
})();
